C('display_decimal_meaning','Bản ghi giả định: nhập 7 ÷ 20 =, màn hình hiển thị 0.35. Hãy diễn giải màn hình và chuyển sang tỉ số phần trăm, không dùng phím phần trăm.', [('Tử','7',''),('Mẫu','20',''),('Màn hình được chép','0.35','')],'Đọc giá trị màn hình và viết tỉ số phần trăm.',[
S('Hiểu màn hình','Dấu chấm trên màn hình biểu diễn dấu phẩy thập phân.','0.35','Đọc không phẩy ba năm; nhân lại với mẫu được tử đã nhập.','7/20',''),S('Chuyển tỉ lệ','Một đơn vị tỉ lệ ứng với một trăm phần trăm.','35','Nhập tiếp phép nhân 100 nếu cần; 35% viết dạng thập phân trở lại 0,35.','{s0}*100','%')],[('Tỉ số phần trăm','35','%')]),
C('estimate_catches_entry','Bản ghi giả định tính tiền 2,4 kg giá 35 nghìn đồng/kg: màn hình ghi 840; lịch sử phím được chép đầy đủ là 24 × 35 =. Chỉ ra chỗ nhập không khớp đề và tính lại.', [('Khối lượng','2.4','kg'),('Đơn giá','35','nghìn đồng/kg'),('Số nhập','24','kg'),('Màn hình','840','nghìn đồng')],'Đối chiếu bản ghi và nêu tiền đúng.',[
S('Đối chiếu dữ kiện','Số khối lượng trong lịch sử khác số đề bài.','84','Đã nhập 24 thay vì 2,4. Chuỗi dự kiến sau xóa: 2 . 4 × 35 =. Hai đến ba kilôgam cho tiền giữa 70 và 105 nghìn đồng, nên màn hình cũ không hợp lý.','2.4*35','nghìn đồng')],[('Tiền đúng','84','nghìn đồng')]),
C('display_not_percentage','Em viết: "Máy cho 0.6 khi tính 9 ÷ 15, nên tỉ lệ là 0,6%". Hãy nhận xét, không dùng phím phần trăm.', [('Phần','9',''),('Toàn bộ','15',''),('Màn hình','0.6','')],'Viết đúng tỉ số phần trăm từ màn hình.',[
S('Phân biệt số thập phân và phần trăm','Màn hình là tỉ số dạng thập phân, chưa phải số phần trăm.','60','Nhân tỉ số với một trăm để viết theo phần trăm; 60% của 15 bằng 9.','0.6*100','%')],[('Tỉ lệ đúng','60','%')],student='Máy cho 0.6 khi tính 9 ÷ 15, nên tỉ lệ là 0,6%',kind='misconception'),
